module sdp_ram #(
  parameter  int DW = 32, DEPTH = 512,
  localparam int AW = $clog2(DEPTH)
) (
  input  logic          clk,
  // write port
  input  logic          we,
  input  logic [AW-1:0] waddr,
  input  logic [DW-1:0] din,
  // read port
  input  logic          re,
  input  logic [AW-1:0] raddr,
  output logic [DW-1:0] dout
);
  logic [DW-1:0] mem [DEPTH];

  always_ff @(posedge clk) begin
    if (we) mem[waddr] <= din;
    if (re) dout <= mem[raddr];     // same address as a write: old data
  end
endmodule

module tdp_ram #(
  parameter  int DW = 32, DEPTH = 1024,
  localparam int AW = $clog2(DEPTH)
) (
  input  logic clka, ena, wea,
  input  logic [AW-1:0] addra,
  input  logic [DW-1:0] dina,
  output logic [DW-1:0] douta,
  input  logic clkb, enb, web,
  input  logic [AW-1:0] addrb,
  input  logic [DW-1:0] dinb,
  output logic [DW-1:0] doutb
);
  logic [DW-1:0] mem [DEPTH];

  // Two processes write the same array, so plain 'always' is used:
  // 'always_ff' does not allow a variable to be written by two blocks.
  always @(posedge clka)
    if (ena) begin
      if (wea) mem[addra] <= dina;
      douta <= mem[addra];
    end

  always @(posedge clkb)
    if (enb) begin
      if (web) mem[addrb] <= dinb;
      doutb <= mem[addrb];
    end
endmodule

module regfile_2r1w #(
  parameter  int DW = 32, N = 32,
  localparam int AW = $clog2(N)
) (
  input  logic          clk, we,
  input  logic [AW-1:0] wa, ra1, ra2,
  input  logic [DW-1:0] wd,
  output logic [DW-1:0] rd1, rd2
);
  logic [DW-1:0] rf [N];

  always_ff @(posedge clk) if (we) rf[wa] <= wd;

  // write-through bypass: reading the register that is being written
  // returns the new value in the same cycle
  assign rd1 = (we && wa == ra1) ? wd : rf[ra1];
  assign rd2 = (we && wa == ra2) ? wd : rf[ra2];
endmodule

// inside tdp_ram, when both ports use the same clock 'clk'
a_no_ww_collision: assert property (
  @(posedge clk) !(ena && wea && enb && web && addra == addrb)
) else $error("write-write collision at address %0h", addra);
